     1→// 🦎 Mini Zig Compiler - Main Entry Point
     2→// src/main.zig: Tokenizer → Parser → AST → AstGen → ZIR → Sema → AIR
     3→
     4→const std = @import("std");
     5→const Tokenizer = @import("tokenizer.zig").Tokenizer;
     6→const Token = @import("tokenizer.zig").Token;
     7→const Parser = @import("parser.zig").Parser;
     8→const Ast = @import("ast.zig");
     9→const printAst = @import("ast.zig").printAst;
    10→const AstGen = @import("astgen.zig").AstGen;
    11→const printZir = @import("zir.zig").printZir;
    12→const Sema = @import("sema.zig").Sema;
    13→const printAir = @import("air.zig").printAir;
    14→
    15→pub fn main() !void {
    16→    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    17→    defer _ = gpa.deinit();
    18→    const allocator = gpa.allocator();
    19→
    20→    // 테스트 소스 코드
    21→    const source =
    22→        \\fn add(a: i32, b: i32) -> i32 {
    23→        \\    return a + b;
    24→        \\}
    25→        \\
    26→        \\fn main() -> i32 {
    27→        \\    const x = add(1, 2);
    28→        \\    const y = x + 3;
    29→        \\    return y;
    30→        \\}
    31→    ;
    32→
    33→    std.debug.print("========== Mini Zig Compiler ==========\n\n", .{});
    34→
    35→    // Step 1: Tokenize
    36→    std.debug.print("[Step 1] TOKENIZE\n", .{});
    37→    std.debug.print("─────────────────────────\n", .{});
    38→
    39→    var tokenizer = Tokenizer.init(source);
    40→    var tokens = std.ArrayList(Token).init(allocator);
    41→    defer tokens.deinit();
    42→
    43→    while (true) {
    44→        const token = tokenizer.nextToken();
    45→        try tokens.append(token);
    46→
    47→        std.debug.print("{s:15} = \"{s}\"\n", .{ @tagName(token.tag), token.lexeme(source) });
    48→
    49→        if (token.tag == .eof) break;
    50→    }
    51→
    52→    std.debug.print("\nTokens: {} total\n\n", .{tokens.items.len});
    53→
    54→    // Step 2: Parse
    55→    std.debug.print("[Step 2] PARSE\n", .{});
    56→    std.debug.print("─────────────────────────\n", .{});
    57→
    58→    var parser = Parser.init(tokens.items, source, allocator);
    59→    const ast = try parser.parseProgram();
    60→
    61→    // AST 출력
    62→    std.debug.print("\nGenerated AST:\n", .{});
    63→    printAst(&ast.root, 0);
    64→
    65→    std.debug.print("\n✅ Parsing successful!\n\n", .{});
    66→
    67→    // Step 3: AstGen (AST → ZIR)
    68→    std.debug.print("[Step 3] ASTGEN (AST → ZIR)\n", .{});
    69→    std.debug.print("─────────────────────────\n", .{});
    70→
    71→    var astgen = try AstGen.init(allocator, source);
    72→    try astgen.genProgram(&ast);
    73→
    74→    std.debug.print("\nGenerated ZIR:\n", .{});
    75→    printZir(astgen.zir, 0);
    76→
    77→    std.debug.print("\n✅ AstGen successful!\n\n", .{});
    78→
    79→    // Step 4: Sema (ZIR → AIR with Type Information)
    80→    std.debug.print("[Step 4] SEMA (ZIR → AIR)\n", .{});
    81→    std.debug.print("─────────────────────────\n", .{});
    82→
    83→    var sema = try Sema.init(allocator, astgen.zir);
    84→    try sema.analyzeProgram();
    85→
    86→    std.debug.print("\nGenerated AIR:\n", .{});
    87→    printAir(sema.air, 0);
    88→
    89→    if (sema.hasErrors()) {
    90→        std.debug.print("\n⚠️ Semantic errors found:\n", .{});
    91→        sema.printErrors();
    92→    }
    93→
    94→    sema.deinit();
    95→    astgen.deinit();
    96→
    97→    std.debug.print("\n✅ Sema successful!\n", .{});
    98→}
