     1→// 🦎 Mini Zig Compiler - Phase 2.4: AIR
     2→// src/air.zig: Analyzed Intermediate Representation (with Type Information)
     3→
     4→const std = @import("std");
     5→
     6→/// Type System
     7→pub const Type = union(enum) {
     8→    void,
     9→    i32,
    10→    i64,
    11→    f32,
    12→    f64,
    13→    bool,
    14→    string,
    15→    array: struct {
    16→        element_ty: *Type,
    17→        len: ?usize,
    18→    },
    19→    function: struct {
    20→        params: []Type,
    21→        return_ty: *Type,
    22→    },
    23→    unknown, // 아직 추론되지 않음
    24→};
    25→
    26→/// AIR Instruction (with Type Information)
    27→pub const Instruction = union(enum) {
    28→    // 리터럴 (타입 정보 포함)
    29→    load_int: struct { value: i64, ty: Type },
    30→    load_float: struct { value: f64, ty: Type },
    31→    load_string: struct { index: u32, ty: Type },
    32→
    33→    // 변수 (타입 정보 포함)
    34→    load_var: struct { name_index: u32, ty: Type },
    35→    store_var: struct { name_index: u32, value: Ref, ty: Type },
    36→
    37→    // 연산자 (연산 결과 타입 포함)
    38→    binary_op: struct { op: BinaryOp, lhs: Ref, rhs: Ref, result_ty: Type },
    39→    unary_op: struct { op: UnaryOp, operand: Ref, result_ty: Type },
    40→
    41→    // 함수
    42→    fn_begin: struct { name_index: u32, params: []Ref, return_ty: Type },
    43→    fn_end,
    44→
    45→    // 제어 흐름
    46→    call: struct { callee: Ref, args: []Ref, return_ty: Type },
    47→    br: Ref,
    48→    cond_br: struct { cond: Ref, then_block: Ref, else_block: ?Ref },
    49→    return_val: ?Ref,
    50→
    51→    // 블록
    52→    block_begin: struct { label: u32 },
    53→    block_end,
    54→
    55→    // 배열/메모리
    56→    array_literal: struct { elements: []Ref, element_ty: Type },
    57→    index_access: struct { array: Ref, index: Ref, element_ty: Type },
    58→    member_access: struct { object: Ref, field_index: u32, field_ty: Type },
    59→
    60→    // 제어 흐름 (advanced)
    61→    loop_begin: struct { label: u32 },
    62→    loop_end,
    63→    break_loop: struct { label: u32 },
    64→    continue_loop: struct { label: u32 },
    65→
    66→    // 기타
    67→    noop,
    68→};
    69→
    70→pub const Ref = u32; // Instruction 인덱스
    71→
    72→pub const BinaryOp = enum {
    73→    add, sub, mul, div, mod,
    74→    eq, ne, lt, le, gt, ge,
    75→    logical_and, logical_or,
    76→    bitwise_and, bitwise_or, bitwise_xor,
    77→    lshift, rshift,
    78→};
    79→
    80→pub const UnaryOp = enum {
    81→    negate, not, bitwise_not,
    82→};
    83→
    84→/// AIR - Analyzed Intermediate Representation
    85→pub const Air = struct {
    86→    instructions: std.ArrayList(Instruction),
    87→    extra: std.ArrayList(u32),
    88→    strings: std.StringHashMap([]const u8),
    89→    allocator: std.mem.Allocator,
    90→
    91→    pub fn init(allocator: std.mem.Allocator) Air {
    92→        return .{
    93→            .instructions = std.ArrayList(Instruction).init(allocator),
    94→            .extra = std.ArrayList(u32).init(allocator),
    95→            .strings = std.StringHashMap([]const u8).init(allocator),
    96→            .allocator = allocator,
    97→        };
    98→    }
    99→
   100→    pub fn deinit(self: *Air) void {
   101→        self.instructions.deinit();
   102→        self.extra.deinit();
   103→        self.strings.deinit();
   104→    }
   105→
   106→    /// 명령어 추가 및 Ref 반환
   107→    pub fn addInstruction(self: *Air, inst: Instruction) !Ref {
   108→        const index: Ref = @intCast(self.instructions.items.len);
   109→        try self.instructions.append(inst);
   110→        return index;
   111→    }
   112→
   113→    /// 문자열 추가 및 인덱스 반환
   114→    pub fn addString(self: *Air, text: []const u8) !u32 {
   115→        if (self.strings.get(text)) |_| {
   116→            return @intCast(self.strings.count() - 1);
   117→        }
   118→
   119→        const index: u32 = @intCast(self.strings.count());
   120→        try self.strings.put(text, text);
   121→        return index;
   122→    }
   123→
   124→    /// 추가 데이터 저장소에 값 추가
   125→    pub fn addExtra(self: *Air, value: u32) !u32 {
   126→        const index: u32 = @intCast(self.extra.items.len);
   127→        try self.extra.append(value);
   128→        return index;
   129→    }
   130→};
   131→
   132→/// Type 유틸리티 함수들
   133→pub fn typeEq(t1: Type, t2: Type) bool {
   134→    switch (t1) {
   135→        .void => return t2 == .void,
   136→        .i32 => return t2 == .i32,
   137→        .i64 => return t2 == .i64,
   138→        .f32 => return t2 == .f32,
   139→        .f64 => return t2 == .f64,
   140→        .bool => return t2 == .bool,
   141→        .string => return t2 == .string,
   142→        .unknown => return t2 == .unknown,
   143→        .array => |arr1| {
   144→            if (t2 == .array) {
   145→                const arr2 = t2.array;
   146→                return typeEq(arr1.element_ty.*, arr2.element_ty.*) and
   147→                    arr1.len == arr2.len;
   148→            }
   149→            return false;
   150→        },
   151→        .function => {
   152→            // 함수 타입 비교는 복잡하므로 나중에 구현
   153→            return false;
   154→        },
   155→    }
   156→}
   157→
   158→pub fn typeName(t: Type) []const u8 {
   159→    return switch (t) {
   160→        .void => "void",
   161→        .i32 => "i32",
   162→        .i64 => "i64",
   163→        .f32 => "f32",
   164→        .f64 => "f64",
   165→        .bool => "bool",
   166→        .string => "string",
   167→        .unknown => "unknown",
   168→        .array => "array",
   169→        .function => "function",
   170→    };
   171→}
   172→
   173→/// AIR 디버깅용 출력 함수
   174→pub fn printAir(air: *const Air, indent: usize) void {
   175→    const spaces = " " ** indent;
   176→    const stdout = std.io.getStdOut().writer();
   177→
   178→    stdout.print("{s}=== AIR Instructions ===\n", .{spaces}) catch {};
   179→
   180→    for (air.instructions.items, 0..) |inst, idx| {
   181→        stdout.print("{s}[{}] ", .{ spaces, idx }) catch {};
   182→
   183→        switch (inst) {
   184→            .load_int => |data| {
   185→                stdout.print("load_int {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   186→            },
   187→            .load_float => |data| {
   188→                stdout.print("load_float {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   189→            },
   190→            .load_string => |data| {
   191→                stdout.print("load_string @{} ({s})\n", .{ data.index, typeName(data.ty) }) catch {};
   192→            },
   193→            .load_var => |data| {
   194→                stdout.print("load_var @{} ({s})\n", .{ data.name_index, typeName(data.ty) }) catch {};
   195→            },
   196→            .store_var => |data| {
   197→                stdout.print("store_var @{} = %{} ({s})\n", .{ data.name_index, data.value, typeName(data.ty) }) catch {};
   198→            },
   199→            .binary_op => |data| {
   200→                stdout.print("binary_op {:s} %{} %{} → {s}\n", .{ @tagName(data.op), data.lhs, data.rhs, typeName(data.result_ty) }) catch {};
   201→            },
   202→            .unary_op => |data| {
   203→                stdout.print("unary_op {:s} %{} → {s}\n", .{ @tagName(data.op), data.operand, typeName(data.result_ty) }) catch {};
   204→            },
   205→            .fn_begin => |data| {
   206→                stdout.print("fn_begin @{} (params: {}, return: {s})\n", .{ data.name_index, data.params.len, typeName(data.return_ty) }) catch {};
   207→            },
   208→            .fn_end => {
   209→                stdout.print("fn_end\n", .{}) catch {};
   210→            },
   211→            .call => |data| {
   212→                stdout.print("call %{} (args: {}, return: {s})\n", .{ data.callee, data.args.len, typeName(data.return_ty) }) catch {};
   213→            },
   214→            .return_val => |ret| {
   215→                if (ret) |r| {
   216→                    stdout.print("return %{}\n", .{r}) catch {};
   217→                } else {
   218→                    stdout.print("return void\n", .{}) catch {};
   219→                }
   220→            },
   221→            .block_begin => |data| {
   222→                stdout.print("block_begin @{}\n", .{data.label}) catch {};
   223→            },
   224→            .block_end => {
   225→                stdout.print("block_end\n", .{}) catch {};
   226→            },
   227→            .array_literal => |data| {
   228→                stdout.print("array_literal (elements: {}, type: {s})\n", .{ data.elements.len, typeName(data.element_ty) }) catch {};
   229→            },
   230→            .noop => {
   231→                stdout.print("noop\n", .{}) catch {};
   232→            },
   233→            else => {
   234→                stdout.print("{s}\n", .{@tagName(inst)}) catch {};
   235→            },
   236→        }
   237→    }
   238→
   239→    stdout.print("{s}=== Strings ===\n", .{spaces}) catch {};
   240→    var iter = air.strings.iterator();
   241→    var idx: u32 = 0;
   242→    while (iter.next()) |entry| {
   243→        stdout.print("{s}@{}: \"{s}\"\n", .{ spaces, idx, entry.value_ptr.* }) catch {};
   244→        idx += 1;
   245→    }
   246→}
