   252→/// Semantic Analyzer (메인 분석기)
   253→pub const Sema = struct {
   254→    zir: *const Zir,
   255→    air: *Air,
   256→    allocator: std.mem.Allocator,
   257→
   258→    symbol_table: SymbolTable,
   259→    type_infer: TypeInference,
   260→
   261→    errors: std.ArrayList(SemanticError),
   262→    current_function: ?[]const u8 = null,
   263→    function_return_type: ?AirType = null,
   264→
   265→    pub fn init(allocator: std.mem.Allocator, zir: *const Zir) !Sema {
   266→        var air = try allocator.create(Air);
   267→        air.* = Air.init(allocator);
   268→
   269→        var symbol_table = SymbolTable.init(allocator, null);
   270→
   271→        return .{
   272→            .zir = zir,
   273→            .air = air,
   274→            .allocator = allocator,
   275→            .symbol_table = symbol_table,
   276→            .type_infer = TypeInference.init(allocator, &symbol_table),
   277→            .errors = std.ArrayList(SemanticError).init(allocator),
   278→        };
   279→    }
   280→
   281→    pub fn deinit(self: *Sema) void {
   282→        self.symbol_table.deinit();
   283→        self.air.deinit();
   284→        self.allocator.destroy(self.air);
   285→        self.errors.deinit();
   286→    }
   287→
   288→    /// 전체 ZIR 분석
   289→    pub fn analyzeProgram(self: *Sema) !void {
   290→        // 1단계: 모든 선언 수집 (forward pass)
   291→        // 2단계: 타입 검사 및 AIR 생성 (analysis pass)
   292→
   293→        // 현재 간단한 구현: 순차적으로 처리
   294→        for (self.zir.instructions.items, 0..) |zir_inst, idx| {
   295→            _ = self.analyzeInstruction(zir_inst, idx) catch |err| {
   296→                // 에러 계속 수집
   297→                continue;
   298→            };
   299→        }
   300→    }
   301→
   302→    /// 개별 명령어 분석
   303→    fn analyzeInstruction(self: *Sema, zir_inst: Zir.Instruction, idx: usize) !void {
   304→        _ = idx;
   305→
   306→        switch (zir_inst) {
   307→            .load_int => |data| {
   308→                _ = try self.air.addInstruction(.{
   309→                    .load_int = .{
   310→                        .value = data.value,
   311→                        .ty = .i32,
   312→                    },
   313→                });
   314→            },
   315→            .load_float => |data| {
   316→                _ = try self.air.addInstruction(.{
   317→                    .load_float = .{
   318→                        .value = data.value,
   319→                        .ty = .f64,
   320→                    },
   321→                });
   322→            },
   323→            .load_string => |data| {
   324→                _ = try self.air.addInstruction(.{
   325→                    .load_string = .{
   326→                        .index = data.index,
   327→                        .ty = .string,
   328→                    },
   329→                });
   330→            },
   331→            .load_var => |data| {
   332→                _ = try self.air.addInstruction(.{
   333→                    .load_var = .{
   334→                        .name_index = data.name_index,
   335→                        .ty = .unknown,
   336→                    },
   337→                });
   338→            },
   339→            .store_var => |data| {
   340→                _ = try self.air.addInstruction(.{
   341→                    .store_var = .{
   342→                        .name_index = data.name_index,
   343→                        .value = data.value,
   344→                        .ty = .unknown,
   345→                    },
   346→                });
   347→            },
   348→            .binary_op => |data| {
   349→                // 타입 검사 수행
   350→                const result_ty = try self.type_infer.inferBinaryOpType(data.op);
   351→                _ = try self.air.addInstruction(.{
   352→                    .binary_op = .{
   353→                        .op = data.op,
   354→                        .lhs = data.lhs,
   355→                        .rhs = data.rhs,
   356→                        .result_ty = result_ty,
   357→                    },
   358→                });
   359→            },
   360→            .unary_op => |data| {
   361→                const result_ty = try self.type_infer.inferUnaryOpType(data.op);
   362→                _ = try self.air.addInstruction(.{
   363→                    .unary_op = .{
   364→                        .op = data.op,
   365→                        .operand = data.operand,
   366→                        .result_ty = result_ty,
   367→                    },
   368→                });
   369→            },
   370→            .fn_begin => |data| {
   371→                _ = try self.air.addInstruction(.{
   372→                    .fn_begin = .{
   373→                        .name_index = data.name_index,
   374→                        .params = data.params,
   375→                        .return_ty = .void, // 기본 반환 타입
   376→                    },
   377→                });
   378→            },
   379→            .fn_end => {
   380→                _ = try self.air.addInstruction(.fn_end);
   381→            },
   382→            .call => |data| {
   383→                _ = try self.air.addInstruction(.{
   384→                    .call = .{
   385→                        .callee = data.callee,
   386→                        .args = data.args,
   387→                        .return_ty = .unknown,
   388→                    },
   389→                });
   390→            },
   391→            .return_val => |ret| {
   392→                _ = try self.air.addInstruction(.{ .return_val = ret });
   393→            },
   394→            .cond_br => |data| {
   395→                _ = try self.air.addInstruction(.{
   396→                    .cond_br = .{
   397→                        .cond = data.cond,
   398→                        .then_block = data.then_block,
   399→                        .else_block = data.else_block,
   400→                    },
   401→                });
   402→            },
   403→            .block_begin => |data| {
   404→                _ = try self.air.addInstruction(.{
   405→                    .block_begin = .{ .label = data.label },
   406→                });
   407→            },
   408→            .block_end => {
   409→                _ = try self.air.addInstruction(.block_end);
   410→            },
   411→            .array_literal => |data| {
   412→                _ = try self.air.addInstruction(.{
   413→                    .array_literal = .{
   414→                        .elements = data.elements,
   415→                        .element_ty = .unknown,
   416→                    },
   417→                });
   418→            },
   419→            .loop_begin => |data| {
   420→                _ = try self.air.addInstruction(.{
   421→                    .loop_begin = .{ .label = data.label },
   422→                });
   423→            },
   424→            .loop_end => {
   425→                _ = try self.air.addInstruction(.loop_end);
   426→            },
   427→            else => {
   428→                // 기타 명령어는 그대로 복사
   429→                _ = try self.air.addInstruction(zir_inst);
   430→            },
   431→        }
   432→    }
   433→
   434→    /// 에러 보고
   435→    pub fn reportError(self: *Sema, err: SemanticError) !void {
   436→        try self.errors.append(err);
   437→    }
   438→
   439→    /// 에러 확인
   440→    pub fn hasErrors(self: *Sema) bool {
   441→        return self.errors.items.len > 0;
   442→    }
   443→
   444→    /// 에러 개수
   445→    pub fn errorCount(self: *Sema) usize {
   446→        return self.errors.items.len;
   447→    }
   448→
   449→    /// 에러 출력
   450→    pub fn printErrors(self: *Sema) void {
   451→        const stdout = std.io.getStdOut().writer();
   452→
   453→        for (self.errors.items) |err| {
   454→            switch (err) {
   455→                .undefined_variable => |data| {
   456→                    stdout.print("Error: undefined variable '{s}'\n  at line {}, column {}\n\n", .{
   457→                        data.name,
   458→                        data.location.line,
   459→                        data.location.column,
   460→                    }) catch {};
   461→                },
   462→                .duplicate_declaration => |data| {
   463→                    stdout.print("Error: duplicate declaration '{s}'\n  at line {}, column {}\n\n", .{
   464→                        data.name,
   465→                        data.location.line,
   466→                        data.location.column,
   467→                    }) catch {};
   468→                },
   469→                .type_mismatch => |data| {
   470→                    stdout.print("Error: type mismatch\n  expected: {s}\n  got: {s}\n  at line {}, column {}\n\n", .{
   471→                        Air.typeName(data.expected),
   472→                        Air.typeName(data.got),
   473→                        data.location.line,
   474→                        data.location.column,
   475→                    }) catch {};
   476→                },
   477→                .wrong_arg_count => |data| {
   478→                    stdout.print("Error: function '{s}' expects {} arguments, got {}\n  at line {}, column {}\n\n", .{
   479→                        data.function,
   480→                        data.expected,
   481→                        data.got,
   482→                        data.location.line,
   483→                        data.location.column,
   484→                    }) catch {};
   485→                },
   486→                .const_reassignment => |data| {
   487→                    stdout.print("Error: cannot reassign constant '{s}'\n  at line {}, column {}\n\n", .{
   488→                        data.name,
   489→                        data.location.line,
   490→                        data.location.column,
   491→                    }) catch {};
   492→                },
   493→                .non_bool_condition => |data| {
   494→                    stdout.print("Error: condition must be boolean, got {s}\n  at line {}, column {}\n\n", .{
   495→                        Air.typeName(data.got),
   496→                        data.location.line,
   497→                        data.location.column,
   498→                    }) catch {};
   499→                },
   500→                .non_function_call => |data| {
   501→                    stdout.print("Error: cannot call non-function type {s}\n  at line {}, column {}\n\n", .{
   502→                        Air.typeName(data.got),
   503→                        data.location.line,
   504→                        data.location.column,
   505→                    }) catch {};
   506→                },
   507→                .invalid_binary_op => |data| {
   508→                    stdout.print("Error: invalid binary operation '{s}' on {s} and {s}\n  at line {}, column {}\n\n", .{
   509→                        data.op,
   510→                        Air.typeName(data.lhs_ty),
   511→                        Air.typeName(data.rhs_ty),
   512→                        data.location.line,
   513→                        data.location.column,
   514→                    }) catch {};
   515→                },
   516→                .invalid_unary_op => |data| {
   517→                    stdout.print("Error: invalid unary operation '{s}' on {s}\n  at line {}, column {}\n\n", .{
   518→                        data.op,
   519→                        Air.typeName(data.operand_ty),
   520→                        data.location.line,
   521→                        data.location.column,
   522→                    }) catch {};
   523→                },
   524→            }
   525→        }
   526→    }
   527→};
